import { $, i, icons, stat, expenseTable, tableHTML, empty } from './ui.js';
import { expenses, notifications } from './api.js';
import { INR, sum, escapeHTML as h, timeLabel, dateLabel } from './utils.js';
import { renderSpendingCharts, destroyCharts } from './charts.js';
import { ticketNotice } from './tickets.js';
import { expenseGroups, expenseTickets, managerClaims, financeClaims } from './expense-state.js';
export function dashboardStats(rows) {
 const {submitted,pending,approved,paid}=expenseGroups(rows);
 return `<div class="stats-grid">${stat('Total submitted',INR(sum(submitted)),`${submitted.length} expense claims`,'wallet','lavender')}${stat('Awaiting approval',INR(sum(pending)),`${pending.length} requests to review`,'clock-3','amber')}${stat('Approved expenses',INR(sum(approved)),`${approved.length} approved, including reimbursed`,'badge-check','blue')}${stat('Reimbursed',INR(sum(paid)),`${paid.length} completed demo payments`,'circle-check','green')}</div>`;
}
export async function employeeDashboard(profile) {
 const expanded=document.getElementById('dashboard-insights')?.open||false;
 const [rows,updates]=await Promise.all([expenses(),notifications(profile.id)]),tickets=expenseTickets(rows);
 const {submitted,pending,approved,paid,outstanding,rejected}=expenseGroups(rows);
 const drafts=rows.filter(r=>r.status==='draft'),needsDetails=tickets.filter(t=>t.status==='awaiting_details');
 const passed=submitted.filter(r=>r.verification_status==='Policy Compliant').length;
 const action=(icon,title,body,link,label)=>`<article class="next-step"><span class="stat-icon lavender">${i(icon)}</span><div><h3>${h(title)}</h3><p>${h(body)}</p><a class="text-button" href="${link}">${h(label)} ${i('arrow-right')}</a></div></article>`;
 $('#page-content').innerHTML=`<section class="panel next-steps section-space" aria-labelledby="next-steps-title"><div class="panel-header"><div><h2 id="next-steps-title">What would you like to do?</h2><p>Start a claim, finish a draft or check what happens next.</p></div></div><div class="next-step-grid">${action('circle-plus','Submit an expense','Have your receipt and purchase details ready.','submit-expense.html','Add expense')}${needsDetails.length?action('landmark',`${needsDetails.length} approved ${needsDetails.length===1?'claim needs':'claims need'} bank details`,'Your reimbursement ticket is ready for you.','reimbursement-tickets.html','Provide bank details'):action('file-pen-line',drafts.length?`${drafts.length} unfinished ${drafts.length===1?'draft':'drafts'}`:'Save it for later',drafts.length?'Continue where you left off. Your draft is already saved.':'You can save an expense draft before submitting it.',drafts.length===1?'submit-expense.html?id='+encodeURIComponent(drafts[0].id):'my-expenses.html?status=draft',drafts.length?'Continue draft':'View drafts')}${action('route','Track your expenses',pending.length?`${pending.length} ${pending.length===1?'claim is':'claims are'} waiting for a manager’s decision.`:'See your receipts, decisions and reimbursement progress.','my-expenses.html','View my expenses')}</div></section>
 ${!profile.manager_id?`<div class="notice" role="status">${i('info')}<div><strong>You can submit now.</strong> A manager has not been assigned yet. Your claims will be saved for review, and an administrator can assign a manager later.</div></div>`:''}
 <div class="stats-grid">${stat('Total submitted',INR(sum(submitted)),`${submitted.length} claims · drafts excluded`,'receipt','lavender')}${stat('Waiting for review',INR(sum(pending)),`${pending.length} pending or flagged claims`,'clock-3','amber')}${stat('Awaiting reimbursement',INR(sum(outstanding)),`${outstanding.length} approved or processing`,'wallet','blue')}${stat('Reimbursed',INR(sum(paid)),`${paid.length} completed demo payments`,'circle-check','green')}</div>
 <section class="panel table-panel"><div class="panel-header"><div><h2>Your latest expenses</h2><p>Open a claim to see its receipt, status and next step.</p></div><a class="text-button" href="my-expenses.html">View all ${i('arrow-right')}</a></div>${rows.length?tableHTML(rows.slice(0,5)):empty('Your first expense starts here','Add your business expense and receipt. You can submit even without an assigned manager.','<a class="button primary" href="submit-expense.html">Submit an expense</a>')}</section>
 <details class="dashboard-insights section-space" id="dashboard-insights" ${expanded?'open':''}><summary><span>${i('chart-no-axes-combined')}Spending & verification details<small>Monthly trends, categories and approval results</small></span>${i('chevron-down')}</summary><div class="insights-content"><div class="middle-grid"><section class="panel"><div class="panel-header"><div><h2>Monthly spending</h2><p>Last six months, grouped by expense date</p></div></div><div class="canvas-wrap"><canvas id="monthly-chart" aria-label="Claims and their reimbursed portion by expense month" role="img"></canvas></div></section><section class="panel"><div class="panel-header"><div><h2>Spending by category</h2><p>All submitted claims, excluding drafts</p></div></div><div class="canvas-wrap"><canvas id="category-chart" role="img" aria-label="Category spending chart"></canvas></div></section></div><section class="panel verify-panel"><div class="panel-header"><div><h2>Verification & decisions</h2><p>Automatic checks support your manager’s review.</p></div><a href="analytics.html" class="text-button">Open full reports ${i('arrow-right')}</a></div><div class="verification-overview"><div><strong>${passed}</strong><span>Policy compliant</span></div><div><strong>${rows.filter(r=>r.status==='flagged').length}</strong><span>Flagged for review</span></div><div><strong>${approved.length}</strong><span>Approved, including reimbursed</span></div><div><strong>${rejected.length}</strong><span>Rejected</span></div></div><p class="insights-note">${submitted.length?Math.round(passed/submitted.length*100):0}% of submissions passed automatic checks. These checks do not prove receipt authenticity.</p></section></div></details>
 <section class="panel"><div class="panel-header"><div><h2>Recent updates</h2><p>Decisions and progress from your workspace</p></div><a href="notifications.html" class="text-button">View notifications ${i('arrow-right')}</a></div><div class="activity-list">${updates.slice(0,3).map(n=>`<div class="activity-item"><span class="activity-dot">${i('bell')}</span><div><p>${h(n.message)}</p><small>${timeLabel(n.created_at)}</small>${n.expense_id?`<a class="text-button" href="expense-details.html?id=${encodeURIComponent(n.expense_id)}">View claim ${i('arrow-right')}</a>`:''}</div></div>`).join('')||empty('No updates yet','Your submission and reimbursement updates will appear here.')}</div></section>`;
 destroyCharts();if(expanded)renderSpendingCharts(rows);
 $('#dashboard-insights').ontoggle=e=>{if(e.currentTarget.open)renderSpendingCharts(rows);else destroyCharts();};icons();
}
export async function myExpenses(profile) {const rows=await expenses();$('#page-content').innerHTML=`${dashboardStats(rows)}<section class="panel"><div class="panel-header"><div><h2>${profile.role==='employee'?'My expenses':'Authorized expenses'}</h2><p>Search, filter, sort and export your visible claims</p></div></div><div id="expense-table"></div></section>`;expenseTable($('#expense-table'),rows,{showEmployee:profile.role!=='employee'});icons();}
export async function managerDashboard(profile) {
 const rows=managerClaims(await expenses(),profile.id),queue=expenseGroups(rows).pending,history=rows.filter(r=>r.approvals.some(a=>a.manager_id===profile.id));
 $('#page-content').innerHTML=`<div class="stats-grid">${stat('Awaiting review',String(queue.length),'Assigned to your account','inbox','lavender')}${stat('Flagged claims',String(queue.filter(r=>r.status==='flagged').length),'Need a documented review','flag','amber')}${stat('Reviewed amount',INR(sum(history)),`${history.length} claims reviewed`,'badge-check','blue')}${stat('Approval rate',`${history.length?Math.round(history.filter(r=>r.status!=='rejected').length/history.length*100):0}%`,'Of your reviewed requests','chart-no-axes-combined','green')}</div><div class="notice">${i('shield-check')}<div><strong>Assigned requests only.</strong> Inspect the receipt before making a decision. Flagged approvals require a comment explaining your review. You cannot approve your own expenses.</div></div><section class="panel section-space"><div class="panel-header"><div><h2>Incoming expense requests</h2><p>${queue.length} claims waiting for your decision</p></div></div><div id="manager-queue"></div></section><section class="panel"><div class="panel-header"><div><h2>Approval history</h2><p>Your previously reviewed claims</p></div></div><div id="manager-history"></div></section>`;
 expenseTable($('#manager-queue'),queue,{showEmployee:true,statusOptions:['pending','flagged']});expenseTable($('#manager-history'),history,{showEmployee:true,statusOptions:['approved','rejected','processing','paid']});icons();
}
export async function financeDashboard() {
 const rows=financeClaims(await expenses()),tickets=expenseTickets(rows);const ready=new Set(tickets.filter(t=>t.status==='submitted').map(t=>t.expense_id)),approved=rows.filter(r=>r.status==='approved'&&ready.has(r.id)),processing=rows.filter(r=>r.status==='processing'),paid=rows.filter(r=>r.status==='paid');
 $('#page-content').innerHTML=`<div class="stats-grid">${stat('Ready for processing',INR(sum(approved)),`${approved.length} approved claims`,'badge-check','lavender')}${stat('Processing',INR(sum(processing)),`${processing.length} reimbursements`,'clock-3','amber')}${stat('Completed',INR(sum(paid)),`${paid.length} simulated payments`,'wallet','green')}${stat('Total finance requests',String(rows.length),'Manager-approved claims only','receipt','blue')}</div><div class="notice">${i('info')}<div><strong>Demo reimbursements.</strong> Employees provide bank details through their approval ticket before processing. ${tickets.filter(t=>t.status==='awaiting_details').length} tickets are awaiting details. <a href="reimbursement-tickets.html">View tickets</a>. Then record a unique demo transaction reference and payment date. This updates the database; no actual money is transferred.</div></div><section class="panel"><div class="panel-header"><div><h2>Reimbursement ledger</h2><p>Open a claim to review or record its next step</p></div></div><div id="finance-table"></div></section>`;
 expenseTable($('#finance-table'),rows,{showEmployee:true,statusOptions:['approved','processing','paid']});icons();
}
